//! The model facts the lowering reads, off the canonical's type.
//!
//! Every lowering fn is generic over `M: ModelFacts` (one type per canonical, generated by
//! `scratchy-model-facts`), and reads its facts as `M::FACT`. A fact group the canonical lacks is
//! `None` there, and a step that reads it is a [`LoweringError::ModelLacks`] naming the group:
//! never a zero standing in for the absent fact.

use super::lowered::{Fact, LoweringError};
use scratchy_ir::facts::{
    Attention, AttnClass, Drafter, Gdn, HeadGeometry, IntermediateSize, KvRope, ModelFacts,
    RopePairing, SoftCap, Vision, VocabSize,
};

/// The decoder's attention.
pub(crate) fn attention<M: ModelFacts>() -> Result<Attention, LoweringError> {
    M::ATTENTION.ok_or(LoweringError::ModelLacks(Fact::Attention))
}

/// The query heads every attention layer projects (both classes', by `Attention`'s law).
pub(crate) fn query_heads<M: ModelFacts>() -> Result<u32, LoweringError> {
    attention::<M>().map(|a| a.class(AttnClass::Full).q_heads().get())
}

/// The config's own head geometry (`head_dim`, `num_key_value_heads`): the sliding class's on a
/// hybrid, every layer's on a uniform model. For a step that carries no class of its own (a gate
/// sized by the query heads, a per-head norm).
pub(crate) fn base<M: ModelFacts>() -> Result<HeadGeometry, LoweringError> {
    geometry::<M>(AttnClass::Sliding)
}

/// One attention class's head geometry.
pub(crate) fn geometry<M: ModelFacts>(class: AttnClass) -> Result<HeadGeometry, LoweringError> {
    attention::<M>().map(|a| a.class(class))
}

/// The rotary pair offset of a class's rope: half its rot window, or half its head on a class
/// whose rope pairs proportionally (Gemma 4's full class).
pub(crate) const fn pair_off(a: Attention, class: AttnClass) -> u32 {
    let g = a.class(class);
    match (class, a.full_pairing()) {
        (AttnClass::Full, RopePairing::Proportional) => g.head_dim().get() / 2,
        _ => g.rot_dim().get() / 2,
    }
}

/// The attention whose spans store K unrotated, re-roped to each reader's position: a model with
/// rotary attention. `None` for one whose cached keys are read as stored.
pub(crate) const fn reroped<M: ModelFacts>() -> Option<Attention> {
    match M::ATTENTION {
        Some(a) if matches!(a.kv_rope(), KvRope::OnRead) => Some(a),
        _ => None,
    }
}

/// Whether a cached key is re-roped to its reader's position ([`reroped`]).
pub(crate) const fn rope_on_read<M: ModelFacts>() -> bool {
    reroped::<M>().is_some()
}

/// The drafts a verify step carries, as a kernel's draft-count constant takes them: the kernels'
/// ABI spells "no drafts" 0. Only at that seam is the absent fact a number.
pub(crate) const fn kernel_drafts<M: ModelFacts>() -> u32 {
    match M::SPEC_DRAFTS {
        Some(d) => d.get(),
        None => 0,
    }
}

/// The vision tower's encoder.
pub(crate) fn vision<M: ModelFacts>() -> Result<Vision, LoweringError> {
    M::VISION.ok_or(LoweringError::ModelLacks(Fact::Vision))
}

/// The Gated-DeltaNet layers' geometry.
pub(crate) fn gdn<M: ModelFacts>() -> Result<Gdn, LoweringError> {
    M::GDN.ok_or(LoweringError::ModelLacks(Fact::Gdn))
}

/// A DFlash2 drafter's geometry.
pub(crate) fn drafter<M: ModelFacts>() -> Result<Drafter, LoweringError> {
    M::DRAFTER.ok_or(LoweringError::ModelLacks(Fact::Drafter))
}

/// The feed-forward's inner width.
pub(crate) fn intermediate<M: ModelFacts>() -> Result<IntermediateSize, LoweringError> {
    M::INTERMEDIATE_SIZE.ok_or(LoweringError::ModelLacks(Fact::IntermediateSize))
}

/// The tanh cap on the final logits.
pub(crate) fn final_logit_softcap<M: ModelFacts>() -> Result<SoftCap, LoweringError> {
    M::FINAL_LOGIT_SOFTCAP.ok_or(LoweringError::ModelLacks(Fact::FinalLogitSoftcap))
}

/// The vocabulary.
pub(crate) fn vocab<M: ModelFacts>() -> Result<VocabSize, LoweringError> {
    M::VOCAB_SIZE.ok_or(LoweringError::ModelLacks(Fact::VocabSize))
}

/// Test models as types: what a test lowers at, in place of a canonical stage 1 generated. A test
/// model's facts are a [`TestFacts`] record, so a test states only what differs from its base
/// (`TestFacts { kv_codec: …, ..TP }`), and [`facts_type!`] makes the record a type. The lowering
/// never sees the record: only the type.
#[cfg(test)]
pub(crate) mod fixtures {
    use crate::tape::lowered::MetalDtype;
    use scratchy_ir::facts::{
        Attention, AttnScale, AttnWindow, BlockSize, CaptureSlots, ConvDim, ConvKernel, Drafter,
        Gdn, GdnHeadDim, GdnHeads, HeadDim, HeadGeometry, HiddenSize, IntermediateSize, KvHeads,
        KvLayers, KvRope, MropeSection, NormWeightOffset, NumDrafts, QueryHeads, RmsNormEps,
        RopePairing, RotDim, ScaleDtype, SoftCap, TargetRouting, Vision, VocabSize,
    };
    use scratchy_ir::facts::{AttnClass, ModelFacts};
    use scratchy_ir::{KvCodec, TqBits};

    /// A test model's facts as one record, so a test's model states only what differs from its
    /// base (`TestFacts { kv_codec: …, ..TP }`); [`facts_type!`] makes the record a type, the way
    /// stage 1 makes a canonical one. The lowering never sees the record: only the type.
    #[derive(Clone, Copy)]
    pub(crate) struct TestFacts {
        pub(crate) attention: Option<Attention>,
        pub(crate) hidden: HiddenSize,
        pub(crate) intermediate: Option<IntermediateSize>,
        pub(crate) vocab: Option<VocabSize>,
        pub(crate) eps: RmsNormEps,
        pub(crate) norm_offset: NormWeightOffset,
        pub(crate) final_softcap: Option<SoftCap>,
        pub(crate) mrope: Option<MropeSection>,
        pub(crate) kv_codec: KvCodec,
        pub(crate) kv_layers: Option<KvLayers>,
        pub(crate) metal_dtype: MetalDtype,
        pub(crate) scale_dtype: ScaleDtype,
        pub(crate) vision: Option<Vision>,
        pub(crate) gdn: Option<Gdn>,
        pub(crate) spec_drafts: Option<NumDrafts>,
        pub(crate) drafter: Option<Drafter>,
        pub(crate) capture_slots: Option<CaptureSlots>,
        pub(crate) target_hidden: HiddenSize,
        pub(crate) target_routing: TargetRouting,
        pub(crate) quant: Option<scratchy_ir::facts::Quantization>,
    }

    /// `facts_type!(Name = record)`: a type whose `ModelFacts` are the record's.
    /// `facts_type!(impl[const N: u32] Ty<N> = record)`: a generic type's, the record reading
    /// its parameters.
    macro_rules! facts_type {
        ($name:ident = $facts:expr) => {
            struct $name;
            $crate::tape::facts::fixtures::facts_type!(impl[] $name = $facts);
        };
        (impl[$($gen:tt)*] $ty:ty = $facts:expr) => {
            impl<$($gen)*> ::scratchy_ir::facts::ModelFacts for $ty {
                const ATTENTION: ::core::option::Option<::scratchy_ir::facts::Attention> = $facts.attention;
                const HIDDEN_SIZE: ::scratchy_ir::facts::HiddenSize = $facts.hidden;
                const INTERMEDIATE_SIZE: ::core::option::Option<::scratchy_ir::facts::IntermediateSize> = $facts.intermediate;
                const VOCAB_SIZE: ::core::option::Option<::scratchy_ir::facts::VocabSize> = $facts.vocab;
                const RMS_NORM_EPS: ::scratchy_ir::facts::RmsNormEps = $facts.eps;
                const NORM_WEIGHT_OFFSET: ::scratchy_ir::facts::NormWeightOffset = $facts.norm_offset;
                const FINAL_LOGIT_SOFTCAP: ::core::option::Option<::scratchy_ir::facts::SoftCap> = $facts.final_softcap;
                const MROPE_SECTION: ::core::option::Option<::scratchy_ir::facts::MropeSection> = $facts.mrope;
                const KV_CODEC: ::scratchy_ir::facts::KvCodec = $facts.kv_codec;
                const KV_CACHE_LAYERS: ::core::option::Option<::scratchy_ir::facts::KvLayers> = $facts.kv_layers;
                const METAL_DTYPE: ::scratchy_ir::facts::MetalDtype = $facts.metal_dtype;
                const SCALE_DTYPE: ::scratchy_ir::facts::ScaleDtype = $facts.scale_dtype;
                const VISION: ::core::option::Option<::scratchy_ir::facts::Vision> = $facts.vision;
                const GDN: ::core::option::Option<::scratchy_ir::facts::Gdn> = $facts.gdn;
                const SPEC_DRAFTS: ::core::option::Option<::scratchy_ir::facts::NumDrafts> = $facts.spec_drafts;
                const DRAFTER: ::core::option::Option<::scratchy_ir::facts::Drafter> = $facts.drafter;
                const CAPTURE_SLOTS: ::core::option::Option<::scratchy_ir::facts::CaptureSlots> = $facts.capture_slots;
                const TARGET_HIDDEN_WIDTH: ::scratchy_ir::facts::HiddenSize = $facts.target_hidden;
                const TARGET_ROUTING: ::scratchy_ir::facts::TargetRouting = $facts.target_routing;
                const QUANT: ::core::option::Option<::scratchy_ir::facts::Quantization> = $facts.quant;
            }
        };
    }
    pub(crate) use facts_type;

    /// A test model's full class's geometry.
    pub(crate) fn full<M: ModelFacts>() -> HeadGeometry {
        M::ATTENTION
            .expect("a test model with attention")
            .class(AttnClass::Full)
    }

    /// A test model's sliding class's geometry.
    pub(crate) fn sliding<M: ModelFacts>() -> HeadGeometry {
        M::ATTENTION
            .expect("a test model with attention")
            .class(AttnClass::Sliding)
    }

    /// The drafts a test model's verify step carries; `0` for none.
    pub(crate) const fn drafts(n: u32) -> Option<NumDrafts> {
        if n == 0 {
            None
        } else {
            Some(NumDrafts::new(n))
        }
    }

    /// A Gated-DeltaNet geometry at a 4-wide convolution.
    pub(crate) const fn gdn_at(nk: u32, nv: u32, hk: u32, hv: u32) -> Gdn {
        Gdn::new(
            GdnHeads::new(nk),
            GdnHeads::new(nv),
            GdnHeadDim::new(hk),
            GdnHeadDim::new(hv),
            ConvKernel::new(4),
            ConvDim::new(2 * (nk * hk) as usize + (nv * hv) as usize),
        )
    }

    /// [`TP`] with a Gated-DeltaNet geometry and its verify step's drafts.
    pub(crate) struct GdnAt<
        const NK: u32,
        const NV: u32,
        const HK: u32,
        const HV: u32,
        const DRAFTS: u32,
    >;
    facts_type!(
        impl[const NK: u32, const NV: u32, const HK: u32, const HV: u32, const DRAFTS: u32]
        GdnAt<NK, NV, HK, HV, DRAFTS> = TestFacts {
            gdn: Some(gdn_at(NK, NV, HK, HV)),
            spec_drafts: drafts(DRAFTS),
            ..TP
        }
    );

    /// A class's head geometry: `nqh` query heads over `nkvh` kv heads of `hd`, its rot window
    /// `rot`, its page `block`.
    pub(crate) const fn geom(nqh: u32, nkvh: u32, hd: u32, rot: u32, block: u32) -> HeadGeometry {
        HeadGeometry::new(
            QueryHeads::new(nqh),
            KvHeads::new(nkvh),
            HeadDim::new(hd),
            RotDim::new(rot),
            BlockSize::new(block),
        )
    }

    /// The fixtures' attention scale, `1/sqrt(64)`.
    pub(crate) const SCALE: AttnScale = AttnScale::new(0.125);

    /// An attention of `sliding` and `full` classes at [`SCALE`], `window` its sliding layers'
    /// (`None`: no sliding layers), its full class's rope pairing `pairing`, its keys' rope
    /// `kv_rope`.
    pub(crate) const fn attn(
        sliding: HeadGeometry,
        full: HeadGeometry,
        window: Option<u32>,
        pairing: RopePairing,
        kv_rope: KvRope,
    ) -> Attention {
        let window = match window {
            Some(w) => Some(AttnWindow::new(w)),
            None => None,
        };
        Attention::new(sliding, full, SCALE, window, pairing, kv_rope)
    }

    /// The lowering tests' `TestParams`' geometry, every class the same: 32 query heads over 4 kv heads of 64, the
    /// whole head rotated, 16-position pages.
    pub(crate) const TP_GEOM: HeadGeometry = geom(32, 4, 64, 64, 16);

    /// A Gemma-4-like full class: 512-wide heads over one kv head, 128 lanes rotated, its page
    /// unified up to 32.
    pub(crate) const GEMMA_FULL: HeadGeometry = geom(32, 1, 512, 128, 32);

    /// The lowering tests' `TestParams`' attention: one class, no window, keys rotated at write.
    pub(crate) const TP_ATTN: Attention = attn(
        TP_GEOM,
        TP_GEOM,
        None,
        RopePairing::Standard,
        KvRope::AtWrite,
    );

    /// The lowering tests' `TestParams`' facts: a Llama-1B-like decoder, bf16, dense KV.
    pub(crate) const TP: TestFacts = TestFacts {
        attention: Some(TP_ATTN),
        hidden: HiddenSize::new(2048),
        intermediate: Some(IntermediateSize::new(8192)),
        vocab: None,
        eps: RmsNormEps::new(1e-5),
        norm_offset: NormWeightOffset::new(0.0),
        final_softcap: None,
        mrope: None,
        kv_codec: KvCodec::Dense,
        kv_layers: None,
        metal_dtype: MetalDtype::Bf16,
        scale_dtype: ScaleDtype::F16,
        vision: None,
        gdn: None,
        spec_drafts: None,
        drafter: None,
        capture_slots: None,
        target_hidden: HiddenSize::new(2048),
        target_routing: TargetRouting::Dense,
        quant: None,
    };
    pub(crate) struct Tp;
    facts_type!(impl[] Tp = TP);

    /// The code width the TurboQuant fixture is built at.
    pub(crate) const TQ_BITS: TqBits = TqBits::new(4);

    /// [`TP`] built with the `turboquant` feature: its KV codec is TurboQuant.
    pub(crate) const TQ: TestFacts = TestFacts {
        kv_codec: KvCodec::TurboQuant(TQ_BITS),
        ..TP
    };
    pub(crate) struct Tq;
    facts_type!(impl[] Tq = TQ);
}
